@mcp.tool(name="concat_jump_lists")
def concat_jump_lists(
    fs: str,
    l2: int,
) -> str:
    """Concatenate two jump instruction lists into one. Use to merge multiple conditional branches or control flow paths during compilation.

    Fonction C++ : luaK_concat
    Type de retour : LUAI_FUNC void
    Args:
        fs: FuncState pointer; the compilation state of the current function
        l2: Second jump list to concatenate (instruction index); will be appended to the first list
    """
    lib = _get_lib()
    fn = lib.luaK_concat
    fn.restype = None
    fn.argtypes = [ctypes.c_char_p, ctypes.POINTER(ctypes.c_int), ctypes.c_int]
    _out_l1 = ctypes.c_int()
    try:
        fn(fs.encode() if isinstance(fs, str) else fs, ctypes.byref(_out_l1), l2)
        return str(_out_l1.value)
    except Exception as e:
        return f"Erreur ctypes : {e}"

