@mcp.tool(name="encode_utf8_escape")
def encode_utf8_escape(
    buff: str,
    x: int,
) -> str:
    """Encode a Unicode codepoint as a UTF-8 escape sequence into a buffer. Call when converting Unicode values to UTF-8 representation.

    Fonction C++ : luaO_utf8esc
    Type de retour : LUAI_FUNC int
    Args:
        buff: Buffer pointer to write UTF-8 escape sequence (char *)
        x: Unicode codepoint value to encode (unsigned long)
    """
    lib = _get_lib()
    fn = lib.luaO_utf8esc
    fn.restype = ctypes.c_int
    fn.argtypes = [ctypes.c_char_p, ctypes.c_int]
    # Buffer mutable : contrairement à un simple `buff.encode()`, ce
    # qui est écrit dedans par la fonction C reste visible après l'appel.
    # Taille en OCTETS (pas en caractères) : une chaîne UTF-8 multi-octets a
    # plus d'octets que de caractères, un buffer dimensionné sur len(s) la
    # tronquerait et corromprait les données côté C.
    _buff_bytes = buff.encode("utf-8")
    _buf_buff = ctypes.create_string_buffer(_buff_bytes, len(_buff_bytes) + 1)
    try:
        result = fn(_buf_buff, x)
        return json.dumps({"result": str(result), "buff": _buf_buff.value.decode("utf-8", errors="replace")})
    except Exception as e:
        return f"Erreur ctypes : {e}"

