@mcp.tool(name="get_ocgcore_version")
def get_ocgcore_version(
) -> str:
    """Retrieve the version information of the OCG core library. Use this to check the current OCG core version.

    Fonction C++ : OCG_GetVersion
    Type de retour : OCGAPI void
    """
    lib = _get_lib()
    fn = lib.OCG_GetVersion
    fn.restype = None
    fn.argtypes = [ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
    _out_major = ctypes.c_int()
    _out_minor = ctypes.c_int()
    try:
        fn(ctypes.byref(_out_major), ctypes.byref(_out_minor))
        return json.dumps({
"major": _out_major.value, "minor": _out_minor.value,         })
    except Exception as e:
        return f"Erreur ctypes : {e}"

